import sys, re
from html.parser import HTMLParser
class P(HTMLParser):
    def __init__(self): super().__init__(convert_charrefs=True); self.tables=[]; self.table=None; self.row=None; self.cell=None
    def handle_starttag(self,tag,attrs):
        if tag=='table':
            self.table=[]; self.tables.append(self.table)
        elif tag=='tr' and self.table is not None:
            self.row=[]; self.table.append(self.row)
        elif tag in ('td','th') and self.row is not None:
            self.cell=[]; self.row.append(self.cell)
    def handle_data(self,data):
        if self.cell is not None: self.cell.append(data)
    def handle_endtag(self,tag):
        if tag in ('td','th'): self.cell=None
        elif tag=='tr': self.row=None
        elif tag=='table': self.table=None
p=P(); p.feed(open(sys.argv[1],encoding='utf-8',errors='ignore').read())
for i,t in enumerate(p.tables):
    rows=[[re.sub(r'\\s+',' ',''.join(c)).strip() for c in row] for row in t]
    rows=[r for r in rows if any(r)]
    if len(rows)>3:
        print('TABLE',i,'rows',len(rows),'first',rows[:4])
